create or replace function public.record_asset_history() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='INSERT' then insert into public.asset_history(asset_id,organization_id,event_type,after_value,actor_id) values(new.id,new.organization_id,'CREATED',to_jsonb(new),auth.uid()); elsif tg_op='UPDATE' then insert into public.asset_history(asset_id,organization_id,event_type,before_value,after_value,actor_id) values(new.id,new.organization_id,case when old.status<>new.status then 'STATUS_CHANGED' else 'UPDATED' end,to_jsonb(old),to_jsonb(new),auth.uid()); end if; return new; end; $$;
create trigger assets_history_after_change after insert or update on public.assets for each row execute function public.record_asset_history();
